"""Owner-registered Bot schedules and immutable run identities."""
VERSION=40
REQUIRED_COLUMNS={'owner_routines':{'routine_id','owner_id','agent_id','room_id','revision','name','instruction','schedule','enabled','profile_fingerprint','next_run_at','created_at','updated_at','deleted_at'},
 'owner_routine_runs':{'run_id','routine_id','owner_id','agent_id','room_id','config_revision','generation','origin','scheduled_at','started_at','completed_at','state','root_event_id','result_event_id','failure_code','connection_id','model_id','max_tool_calls','max_executor_seconds'},
 'owner_routine_commands':{'owner_id','command_key','request_digest','response'},
 'owner_routine_pending_tests':{'request_id','owner_id','agent_id','routine_id','config_revision','room_id','root_request_event_id','source_generation','activity_event_id','state','run_id','failure_code','created_at'}}
def upgrade(db):
    db.execute('''CREATE TABLE owner_routines (routine_id VARCHAR(36) PRIMARY KEY,owner_id INTEGER NOT NULL REFERENCES users(id),agent_id INTEGER NOT NULL REFERENCES agents(id),room_id INTEGER NOT NULL REFERENCES conversations(id),revision INTEGER NOT NULL CHECK(revision>=1),name VARCHAR(120) NOT NULL,instruction TEXT NOT NULL,schedule JSON NOT NULL,enabled BOOLEAN NOT NULL CHECK(enabled IN (0,1)),profile_fingerprint VARCHAR(64) NOT NULL,next_run_at DATETIME,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,deleted_at DATETIME)''')
    db.execute('''CREATE TABLE owner_routine_runs (run_id VARCHAR(36) PRIMARY KEY,routine_id VARCHAR(36) NOT NULL REFERENCES owner_routines(routine_id),owner_id INTEGER NOT NULL REFERENCES users(id),agent_id INTEGER NOT NULL REFERENCES agents(id),room_id INTEGER NOT NULL REFERENCES conversations(id),config_revision INTEGER NOT NULL,generation INTEGER NOT NULL,origin VARCHAR(12) NOT NULL CHECK(origin IN ('scheduled','test')),scheduled_at DATETIME NOT NULL,started_at DATETIME NOT NULL,completed_at DATETIME,state VARCHAR(16) NOT NULL,root_event_id VARCHAR(36) NOT NULL REFERENCES room_events(event_id),result_event_id VARCHAR(36) REFERENCES room_events(event_id),failure_code VARCHAR(64),connection_id INTEGER,model_id VARCHAR(200),max_tool_calls INTEGER NOT NULL,max_executor_seconds INTEGER NOT NULL,UNIQUE(routine_id,origin,scheduled_at))''')
    db.execute('CREATE INDEX ix_owner_routine_runs ON owner_routine_runs(routine_id,started_at)')
    db.execute('''CREATE TABLE owner_routine_commands (owner_id INTEGER NOT NULL REFERENCES users(id),command_key VARCHAR(100) NOT NULL,request_digest VARCHAR(64) NOT NULL,response JSON NOT NULL,PRIMARY KEY(owner_id,command_key))''')

    db.execute('''CREATE TABLE owner_routine_pending_tests (request_id VARCHAR(64) PRIMARY KEY,owner_id INTEGER NOT NULL REFERENCES users(id),agent_id INTEGER NOT NULL REFERENCES agents(id),routine_id VARCHAR(36) NOT NULL REFERENCES owner_routines(routine_id),config_revision INTEGER NOT NULL,room_id INTEGER NOT NULL REFERENCES conversations(id),root_request_event_id VARCHAR(36) NOT NULL REFERENCES room_events(event_id),source_generation INTEGER NOT NULL,activity_event_id VARCHAR(36) NOT NULL REFERENCES room_events(event_id),state VARCHAR(16) NOT NULL,run_id VARCHAR(36) REFERENCES owner_routine_runs(run_id),failure_code VARCHAR(64),created_at DATETIME NOT NULL)''')
